content:
260                          DPRINTF("not more", uc, *ucp);
   261                          *ucp = uc - 1;
   262                          goto out;
   263                  }
   264          }
   265  out:
   266          DPRINTF("Bad object: ", uc, *ucp);
   267          *ucp = uc;
   268          return 0;
   269  }
