   271  static int
   272  json_parse_number(const unsigned char **ucp, const unsigned char *ue,
   273      size_t lvl __file_debugused)
   274  {
   275          const unsigned char *uc = *ucp;
   276          int got = 0;
   277
   278          DPRINTF("Parse number: ", uc, *ucp);
   279          if (uc == ue)
   280                  return 0;
   281          if (*uc == '-')
   282                  uc++;
   283
   284          for (; uc < ue; uc++) {
   285                  if (!json_isdigit(*uc))
   286                          break;
   287                  got = 1;
   288          }
   289          if (uc == ue)
   290                  goto out;
   291          if (*uc == '.')
   292                  uc++;
   293          for (; uc < ue; uc++) {
   294                  if (!json_isdigit(*uc))
   295                          break;
   296                  got = 1;
   297          }
   298          if (uc == ue)
   299                  goto out;
   300          if (got && (*uc == 'e' || *uc == 'E')) {
   301                  uc++;
   302                  got = 0;
   303                  if (uc == ue)
   304                          goto out;
   305                  if (*uc == '+' || *uc == '-')
   306                          uc++;
   307                  for (; uc < ue; uc++) {
   308                          if (!json_isdigit(*uc))
   309                                  break;
   310                          got = 1;
   311                  }
   312          }
   313  out:
   314          if (!got)
   315                  DPRINTF("Bad number: ", uc, *ucp);
   316          else
   317                  DPRINTF("Good number: ", uc, *ucp);
   318          *ucp = uc;
   319          return got;
   320  }
