   322  static int
   323  json_parse_const(const unsigned char **ucp, const unsigned char *ue,
   324      const char *str, size_t len, size_t lvl __file_debugused)
   325  {
   326          const unsigned char *uc = *ucp;
   327
   328          DPRINTF("Parse const: ", uc, *ucp);
   329          *ucp += --len - 1;
   330          for (; uc < ue && --len;) {
   331                  if (*uc++ != *++str) {
   332                          DPRINTF("Bad const: ", uc, *ucp);
   333                          return 0;
   334                  }
   335          }
   336          DPRINTF("Good const: ", uc, *ucp);
   337          return 1;
   338  }
