   340  static int
   341  json_parse(const unsigned char **ucp, const unsigned char *ue,
   342      size_t *st, size_t lvl)
   343  {
   344          const unsigned char *uc, *ouc;
   345          int rv = 0;
   346          int t;
   347
   348          ouc = uc = json_skip_space(*ucp, ue);
   349          if (uc == ue)
   350                  goto out;
   351
   352          // Avoid recursion
   353          if (lvl > 500) {
   354                  DPRINTF("Too many levels", uc, *ucp);
   355                  return 0;
   356          }
   357  #if JSON_COUNT
   358          /* bail quickly if not counting */
   359          if (lvl > 1 && (st[JSON_OBJECT] || st[JSON_ARRAYN]))
   360                  return 1;
   361  #endif
   362
   363          DPRINTF("Parse general: ", uc, *ucp);
   364          switch (*uc++) {
   365          case '"':
   366                  rv = json_parse_string(&uc, ue, lvl + 1);
   367                  t = JSON_STRING;
   368                  break;
   369          case '[':
   370                  rv = json_parse_array(&uc, ue, st, lvl + 1);
   371                  t = JSON_ARRAY;
   372                  break;
   373          case '{': /* '}' */
   374                  rv = json_parse_object(&uc, ue, st, lvl + 1);
   375                  t = JSON_OBJECT;
   376                  break;
   377          case 't':
   378                  rv = json_parse_const(&uc, ue, "true", sizeof("true"), lvl + 1);
   379                  t = JSON_CONSTANT;
   380                  break;

380                  break;
   381          case 'f':
   382                  rv = json_parse_const(&uc, ue, "false", sizeof("false"),
   383                      lvl + 1);
   384                  t = JSON_CONSTANT;
   385                  break;
   386          case 'n':
   387                  rv = json_parse_const(&uc, ue, "null", sizeof("null"), lvl + 1);
   388                  t = JSON_CONSTANT;
   389                  break;
   390          default:
   391                  --uc;
   392                  rv = json_parse_number(&uc, ue, lvl + 1);
   393                  t = JSON_NUMBER;
   394                  break;
   395          }
   396          if (rv)
   397                  st[t]++;
   398          uc = json_skip_space(uc, ue);
   399  out:
   400          DPRINTF("End general: ", uc, *ucp);
   401          *ucp = uc;
   402          if (lvl == 0) {
   403                  if (!rv)
   404                          return 0;
   405                  if (uc == ue)
   406                          return (st[JSON_ARRAYN] || st[JSON_OBJECT]) ? 1 : 0;
   407                  if (*ouc == *uc && json_parse(&uc, ue, st, 1))
   408                          return (st[JSON_ARRAYN] || st[JSON_OBJECT]) ? 2 : 0;
   409                  else
   410                          return 0;
   411          }
   412          return rv;
   413  }
